function showMemory(){if(!memoryQueue.length||popups.windows.size)return;openModal(memoryOverlay(memoryQueue[0]),false,'memory');}
popups.onClose=id=>{popupControls?.hide();if(id==='memory')memoryQueue.shift();setTimeout(showMemory,0);if(id==='loot')selectedLootId=null;if(id==='activity'&&game)game.activity=null;if(id==='person'){pendingSlot=null;if(game)buildActions();}if(id==='death'&&game?.dead)game.respawn();};

