// Großer Hinweis „Du wirst angegriffen“: Ereignis `attacked` der Engine, Rückfall auf den Wechsel inCombat 0→1.
const UNDER_ATTACK=COMBAT_TEXT.underAttack||'Du wirst angegriffen';
let attackWarnUntil=0,attackWarnText='',lastInCombat=0,sawAttackEvent=false;
function warnAttacked(name){const el=document.querySelector('#attackWarning');if(!el||!game)return;attackWarnText=UNDER_ATTACK+(name?' · '+name:'');attackWarnUntil=game.time+3;el.textContent=attackWarnText;el.classList.remove('hidden');el.classList.remove('pulse');void el.offsetWidth;el.classList.add('pulse');}
// Beute-Log: jede Zeile kommt aus dem Ereignis `loot` (§8.2). Namen, Seltenheit und Icon aus dem Register.
const LOOT_LINES=50;const lootLines=[];
function lootLine(ev){
 for(const e of ev.items||[])lootLines.push({id:e.id,count:e.count,rarity:e.rarity,source:ev.source?.name||''});
 if(ev.coins)lootLines.push({id:'coins',count:ev.coins,rarity:ITEMS.coins?.rarity||'common',source:ev.source?.name||''});
 while(lootLines.length>LOOT_LINES)lootLines.shift();
 const log=$('#lootLog');if(!log)return;
 log.innerHTML=lootLines.map(l=>'<div class="loot-line" tabindex="0" data-tooltip-item="'+l.id+'" data-item-context="loot"><canvas width="24" height="24" data-item-art="'+(ITEMS[l.id]?.icon||l.id)+'"></canvas><b class="rarity-'+l.rarity+'">'+(ITEMS[l.id]?.name||l.id)+'</b>'+(l.count>1?'<span>× '+l.count+'</span>':'')+(l.source?'<small>'+l.source+'</small>':'')+'</div>').join('');
 log.querySelectorAll('[data-item-art]').forEach(c=>paintItem(c,c.dataset.itemArt));
 log.scrollTop=log.scrollHeight;
}
