let previewDirection='se';
document.addEventListener('click',e=>{if(e.target.closest('[data-preview-turn]')){const dirs=['se','sw','nw','ne'];previewDirection=dirs[(dirs.indexOf(previewDirection)+1)%4];paintRpg();}});
function paintRpg(){paintUiControls();paintDescribeIcons(document,game);paintSpecIcons(document);paintTalentIcons(document);document.querySelectorAll('[data-item-art]').forEach(c=>paintItem(c,c.dataset.itemArt));document.querySelectorAll('#popupLayer [data-skill-art]').forEach(c=>paintSkillIcon(c,c.dataset.skillArt,game.member.id));document.querySelectorAll('[data-item-art],[data-skill-art],[data-spec-art],[data-talent-art],[data-ui-icon]').forEach(styleIcon);for(const cv of document.querySelectorAll('[data-character-art]')){const c=cv.getContext('2d');c.clearRect(0,0,cv.width,cv.height);c.save();c.imageSmoothingEnabled=false;c.scale(cv.width/144,cv.height/180);drawHero(c,72,161,0,{facing:1,direction:previewDirection,classId:game.member.id,visualEquipment:equipmentAppearance(game.rpg.equipment,ITEMS)},false,4);c.restore();}}
