function settingsPanel(){return `<div class="help-settings"><p>${PANEL_UI.settingsIntro}</p><button type="button" data-shell="mobile">Steuerung & Touchbuttons</button><button type="button" data-shell="install">Als App installieren</button><button type="button" data-setting-toggle="autoLoot" aria-pressed="${game.settings.autoLoot}">Auto-Loot: ${game.settings.autoLoot?'an':'aus'}</button><a href="./redesign-demo.html" target="_blank" rel="noopener">Helden & Ausr?stung ?</a><button type="button" data-settings="sound">Ton an / aus</button><button type="button" data-settings="fullscreen">Vollbild</button>${mobile?.active?'<button type="button" data-settings="touchmenu">App-Status & Update</button>':''}<a href="./world-forge.html" target="_blank" rel="noopener">Weltschmiede ↗</a><button type="button" class="help-settings-admin" data-shell="admin">Admin · Neustart, Sicherung, Trainingsarena</button><p class="build-line" data-build>${buildLabel(BUILD)}</p></div>`;}
