function showJournal(tab){const w=openModal('<div class="quest-log">'+questlogPanel(game,questFilter)+'</div><div class="quest-base">'+basePanel(game)+'</div><div class="quest-memories">'+memoriesPanel(game)+'</div>',false,'quest');paintRpg();selectTab(w,tab);}
/** Ein Verweis aus einem Tooltip: Reiter „Kniffe“ öffnen und zur Kachel mit dieser Element-ID springen. */
function showDescribe(anchor){showGuide(PANEL_UI.skills);popups.focus('guide');requestAnimationFrame(()=>{const el=document.getElementById(anchor);if(!el)return;el.scrollIntoView({block:'center'});el.classList.add('kniff-jumped');el.focus?.({preventScroll:true});setTimeout(()=>el.classList.remove('kniff-jumped'),1600);});}
function restAtShrine(){const p=game.player;if(p.inCombat>0){toast('Der Konterbrunnen kann nur außerhalb des Kampfes genutzt werden.');return;}p.hp=p.maxHp;p.energy=100;game.effect('heal',p.x,p.y,{life:1,max:1});toast('Die Quelle erfrischt dich. Leben und Randale wiederhergestellt.');}
/** Ein Ort für die Aktionstaste. Die Rangfolge kommt vollständig aus `game.interaction()`
 *  (Auftragsziel vor Mentor vor Nebenquest vor Ida vor Konterbrunnen, P3/P5) – die UI baut nur
 *  die Beschriftungen aus dem Spielzustand (Sammelgut, Mentor, Nebenquest, Ida). */
function worldInteraction(){
  const it=game.interaction?.();
  if(!it)return null;
  const offer=extra=>({...it,...extra});
  switch(it.kind){
    case 'loot':return offer({label:'Beutel durchsuchen',run:()=>showLoot(it.id)});
    case 'gather':return offer({label:(ITEMS[it.item]?.name||'Material')+' sammeln',run:()=>{game.collectGather(it.id);events();}});
    case 'mentor':return offer({label:'Mit '+it.name+' reden',run:()=>{game.talkToMentor(it.id);events();}});
    case 'item':return offer({run:()=>{game.collectQuestItem(it.quest.id,it.item.id);events();}});
    case 'giver':return offer({run:()=>showSideQuest(it.quest)});
    case 'npc':return offer({label:'Mit '+(it.name||world.npc.name)+' sprechen',run:()=>openModal(idaDialogue(game))});
    case 'shrine':return offer({label:'Am Konterbrunnen rasten',run:restAtShrine});
    default:return null;
  }
}
function speak(){
  if(game.dead)return;
  if(tutorialActive(game)){const bag=nearestLoot(game);if(bag)showLoot(bag.id);else if((game.tutorial.step===0||game.tutorial.step===7)&&distance(game.player,world.npc)>=50)game.navigate(world.npc);else showTutorial();return;}
  worldInteraction()?.run();
}
