function sound(id){if(muted)return;try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const o=audioContext.createOscillator(),gain=audioContext.createGain(),t=audioContext.currentTime;const f={strike:340,mark:520,burst:190,interrupt:680,parry:440,dash:210,heal:700,hit:95,target:850}[id]||300;o.type=['burst','hit'].includes(id)?'triangle':'sine';o.frequency.setValueAtTime(f,t);o.frequency.exponentialRampToValueAtTime(f*(id==='heal'?1.6:.45),t+.18);gain.gain.setValueAtTime(.035,t);gain.gain.exponentialRampToValueAtTime(.001,t+.22);o.connect(gain);gain.connect(audioContext.destination);o.start();o.stop(t+.23);}catch{muted=true;}}
